import React from "react";
import { useLocation } from "react-router-dom";

function getTitleFromPathname(pathname) {
  if (pathname === "/") return "Hematrik Dashboard";
  if (pathname.startsWith("/monitoring")) return "Detection Monitoring";
  if (pathname.startsWith("/history")) return "History";
  if (pathname.startsWith("/profile")) return "Profile";
  return "Not Found";
}

export default function Topbar({ search, setSearch, onToggleSidebar }) {
  const location = useLocation();
  const title = getTitleFromPathname(location.pathname);

  return (
    <header className="topbar">
      <div className="topbar__left">
        <button
          className="iconBtn"
          type="button"
          aria-label="Toggle menu"
          onClick={onToggleSidebar}
        >
          ☰
        </button>
        <div className="topbar__title">{title}</div>
      </div>

      <div className="topbar__actions">
        <div className="search">
          <input
            className="search__input"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search"
            aria-label="Search"
          />
        </div>
      </div>
    </header>
  );
}
